-- Minimal replica of the tables pie.rank_candidates / pie.decide touch on live V2
-- (column lists copied from live information_schema on 2026-10-14). Test use only.
create schema pie; create schema amc;
create table public.subjects(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, sort_order int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.questions(id uuid primary key default gen_random_uuid(), zyntra_id text unique, subject_id uuid not null references public.subjects(id), subtopic_id uuid, stem text not null, options jsonb not null, correct_answer text not null, explanation text, difficulty_tier text, status text not null default 'active', version int not null default 1, provenance jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.practice_sessions(id uuid primary key default gen_random_uuid(), user_id uuid not null, session_type text not null, status text not null default 'active', config jsonb not null default '{}', started_at timestamptz, completed_at timestamptz, last_activity_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.practice_session_questions(id uuid primary key default gen_random_uuid(), session_id uuid not null, question_id uuid not null, position int not null, presented_at timestamptz, answered_at timestamptz, created_at timestamptz not null default now());
create table public.user_attempts(id uuid primary key default gen_random_uuid(), user_id uuid not null, question_id uuid not null, session_id uuid, selected_answer text not null, is_correct boolean not null, created_at timestamptz not null default now());
create table pie.concept(id uuid primary key default gen_random_uuid(), concept_key text not null, title text not null, description text, status text not null default 'active');
create table pie.learning_objective(id uuid primary key default gen_random_uuid(), lo_key text not null unique, concept_id uuid not null references pie.concept(id), title text not null, description text, status text not null default 'active');
create table pie.question_lo(question_id uuid not null references public.questions(id) on delete cascade, lo_id uuid not null references pie.learning_objective(id), is_primary boolean not null default false, weight numeric not null default 1, mapping_source text not null default 'manual', primary key(question_id, lo_id));
create table pie.learner_lo_state(user_id uuid not null, lo_id uuid not null, exposure_count int not null default 0, mastery numeric not null default 0, uncertainty numeric not null default 1, last_seen_at timestamptz, confident_wrong int not null default 0, fragile_correct int not null default 0, primary key(user_id, lo_id));
create table pie.selection_policy(policy_version text primary key, status text not null default 'active', weights jsonb not null, notes text not null, created_at timestamptz not null default now());
create table pie.pie_question_quarantine(id uuid primary key default gen_random_uuid(), question_id uuid not null, reason text not null, status text not null default 'open');
create table pie.lo_prerequisite(lo_id uuid not null, prerequisite_lo_id uuid not null);
create table pie.decision_trace(id uuid primary key default gen_random_uuid(), user_id uuid not null, session_id uuid, question_id uuid, decision_type text not null, selected_action jsonb not null, rejected_actions jsonb not null default '[]', reason_codes text[] not null default '{}', evidence_snapshot jsonb not null default '{}', state_snapshot jsonb not null default '{}', policy_version text not null, model_version text, confidence numeric, source text not null default 'shadow', created_at timestamptz not null default now());
create table amc.amc_blueprint(id uuid primary key default gen_random_uuid(), plugin_version_id uuid, blueprint_key text not null, version text not null, content jsonb not null default '{}', effective_from timestamptz, effective_to timestamptz);
create table amc.amc_blueprint_lo(blueprint_id uuid not null, lo_id uuid not null, eligible boolean not null default true, coverage_target numeric, tie_break_rank int);
